name: Dependabot Auto Merge

on:
  pull_request:
    types: [opened, synchronize, reopened]
  workflow_run:
    workflows: ["Only CI/CT"]
    types: [completed]

permissions:
  contents: read

jobs:
  check-pr:
    runs-on: ubuntu-latest
    permissions:
      pull-requests: read
      checks: read
      contents: read
    outputs:
      pr_number: ${{ steps.set-pr.outputs.pr_number }}
      is_dependabot: ${{ steps.set-pr.outputs.is_dependabot }}
      is_fork: ${{ steps.set-pr.outputs.is_fork }}
      has_validation: ${{ steps.set-pr.outputs.has_validation }}
      checks_passed: ${{ steps.set-pr.outputs.checks_passed }}
    steps:
      - name: Set PR info
        id: set-pr
        uses: actions/github-script@v6
        with:
          script: |
            const event = github.event;
            let pr;
            if (event.pull_request) {
              pr = event.pull_request;
            } else if (event.workflow_run && event.workflow_run.pull_requests && event.workflow_run.pull_requests.length > 0) {
              pr = event.workflow_run.pull_requests[0];
            } else {
              core.setFailed('No pull request found in event');
              return;
            }
            const prNumber = pr.number;
            const author = pr.user.login;
            const isDependabot = author === 'dependabot[bot]';
            const isFork = pr.head.repo.fork;
            const { data: status } = await github.repos.getCombinedStatusForRef({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: pr.head.sha
            });
            const hasValidation = status.state !== 'no_status';
            const { data: checkRuns } = await github.checks.listForRef({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: pr.head.sha
            });
            let checksPassed = true;
            if (checkRuns.total_count === 0) {
              checksPassed = false;
            } else {
              for (const run of checkRuns.check_runs) {
                if (
                  run.conclusion === 'failure' ||
                  run.conclusion === 'cancelled' ||
                  run.conclusion === 'timed_out' ||
                  run.conclusion === 'action_required'
                ) {
                  checksPassed = false;
                  break;
                }
              }
            }
            core.setOutput('pr_number', prNumber);
            core.setOutput('is_dependabot', isDependabot);
            core.setOutput('is_fork', isFork);
            core.setOutput('has_validation', hasValidation);
            core.setOutput('checks_passed', checksPassed);
      - name: Wait for status propagation
        if: github.event_name == 'workflow_run'
        run: sleep 5

  merge-pr:
    needs: check-pr
    if: github.event_name == 'workflow_run' &&
        needs.check-pr.outputs.is_dependabot == 'true' &&
        needs.check-pr.outputs.is_fork == 'false' &&
        needs.check-pr.outputs.has_validation == 'true' &&
        needs.check-pr.outputs.checks_passed == 'true'
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - name: Approve PR
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = ${{ needs.check-pr.outputs.pr_number }};
            const { data: reviews } = await github.pulls.listReviews({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });
            const hasApproved = reviews.some(r => r.state === 'APPROVED');
            if (!hasApproved) {
              await github.pulls.createReview({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: prNumber,
                event: 'APPROVE'
              });
            }
      - name: Merge PR
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = ${{ needs.check-pr.outputs.pr_number }};
            const { data: pr } = await github.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });
            if (pr.merged) {
              core.info('PR already merged');
              return;
            }
            await github.pulls.merge({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber,
              merge_method: 'squash',
              commit_title: pr.title,
              commit_message: pr.body
            });
